 "An empty React project.": "Ein leeres React-Projekt.",
 "An empty repository works best. If the branch is protected on GitHub, type a new one, such as storelib, and Storelib makes it.": "Ein leeres Repository funktioniert am besten. Ist der Branch auf GitHub geschützt, gib einen neuen ein, etwa storelib, und Storelib legt ihn an.",
 "An error occurred": "Ein Fehler ist aufgetreten",
 "An error occurred while saving. Please try again.": "Beim Speichern ist ein Fehler aufgetreten. Versuch es noch mal.",
 "An error occurred. Please try again.": "Ein Fehler ist aufgetreten. Versuch es noch mal.",
 "An export from Judge.me, Yotpo, Loox, Stamped.io, Okendo, Reviews.io, Trustpilot, Google, Etsy, Amazon, WooCommerce, Fera, Ali Reviews or Rivyo, or any CSV or JSON file.": "Ein Export aus Judge.me, Yotpo, Loox, Stamped.io, Okendo, Reviews.io, Trustpilot, Google, Etsy, Amazon, WooCommerce, Fera, Ali Reviews oder Rivyo, oder eine beliebige CSV- oder JSON-Datei.",
 "An hour after a buyer leaves checkout without paying, if they asked for news.": "Eine Stunde, nachdem ein Käufer den Checkout ohne Zahlung verlässt, wenn er Neuigkeiten wollte.",
 "An hour after a buyer leaves checkout without paying, if they asked for news. Turn it on in Checkout.": "Eine Stunde nachdem ein Käufer den Checkout ohne Zahlung verlässt, wenn er Neuigkeiten wollte. Schalte es unter Checkout ein.",
 "An hour after someone presses Pay and no order comes of it. Only people who ticked “Email me news and offers” at checkout, or are on your list, get it, and it stops the moment they buy.": "Eine Stunde, nachdem jemand auf Bezahlen tippt und keine Bestellung daraus wird. Nur wer beim Checkout „Schick mir Neuigkeiten und Angebote“ angehakt hat oder auf deiner Liste steht, bekommt sie, und sie stoppt, sobald gekauft wird.",
 "An icon beside the title": "Ein Icon neben dem Titel",
 "An image beside the title": "Ein Bild neben dem Titel",
 "An image or GIF": "Ein Bild oder GIF",
 "An integration connects Storelib to a service you already use: Google Analytics, a pixel for your ads, a shipping or print on demand company.": "Eine Integration verbindet Storelib mit einem Dienst, den du schon nutzt: Google Analytics, ein Pixel für deine Anzeigen, ein Versand- oder Print-on-Demand-Anbieter.",
 "An intro video": "Ein Intro-Video",
 "An invite is already an approval, so this only applies to anyone who asks without one.": "Eine Einladung ist schon eine Freigabe, das gilt also nur für Anfragen ohne Einladung.",
 "An invite lasts 1 to 365 days.": "Eine Einladung gilt 1 bis 365 Tage.",
 "An invite link is the only way in.": "Ein Einladungslink ist der einzige Weg rein.",
 "An order": "Eine Bestellung",
 "An order, a payout, a dispute, your website or something that isn't working. A real person at Storelib reads every one and replies here.": "Eine Bestellung, eine Auszahlung, eine Anfechtung, deine Website oder etwas, das nicht funktioniert. Ein echter Mensch bei Storelib liest jede Anfrage und antwortet hier.",
 "An unticked “Email me with news and offers” box under the email. Only buyers who tick it get your campaigns.": "Ein nicht angehaktes Feld „Schick mir Neuigkeiten und Angebote“ unter der E-Mail. Nur wer es anhakt, bekommt deine Kampagnen.",
