 "Ask for a change": "Um eine Änderung bitten",
 "Ask for a change, such as “make the hero taller”. It reads AGENTS.md first.": "Bitte um eine Änderung, etwa „mach den Hero höher“. Es liest zuerst AGENTS.md.",
