 "Astrology": "Astrologie",
 "At": "Um",
 "At a glance": "Auf einen Blick",
 "At a time": "Zu einer Uhrzeit",
 "At checkout": "Beim Checkout",
 "At checkout Storelib adds the tax your settings above call for, shows it to the buyer, puts it on the receipt and keeps the record here. Nothing has to be set up before you can sell.": "An der Kasse fügt Storelib die Steuer hinzu, die deine Einstellungen oben vorsehen, zeigt sie dem Käufer, setzt sie auf die Quittung und speichert den Eintrag hier. Du musst nichts einrichten, bevor du verkaufen kannst.",
 "At checkout Storelib adds the tax your settings below call for, shows it to the buyer, puts it on the receipt and keeps the record here. Nothing has to be set up before you can sell.": "An der Kasse fügt Storelib die Steuer hinzu, die deine Einstellungen unten vorsehen, zeigt sie dem Käufer, setzt sie auf die Quittung und speichert den Eintrag hier. Du musst nichts einrichten, bevor du verkaufen kannst.",
 "At checkout Storelib looks at where the buyer is and adds that region's rate. Buyers anywhere else pay no tax.": "Im Checkout schaut Storelib, wo der Käufer ist, und addiert den Satz dieser Region. Käufer anderswo zahlen keine Steuer.",
 "At checkout the buyer types their address. Storelib finds the zone it falls in and shows that zone's rates. An address in no zone cannot check out, so add every country you ship to.": "Im Checkout gibt der Käufer seine Adresse ein. Storelib findet die passende Zone und zeigt deren Tarife. Eine Adresse ohne Zone kann nicht bezahlen, also füg jedes Land hinzu, in das du versendest.",
 "At least 7 days. A card is taken at sign up and charged when the trial ends, unless they cancel.": "Mindestens 7 Tage. Bei der Anmeldung wird eine Karte hinterlegt und am Ende des Testzeitraums belastet, außer sie kündigen.",
 "At most {amount} can go back.": "Höchstens {amount} können zurückgehen.",
 "At most {value}.": "Höchstens {value}.",
 "At or below it is low, for every product without its own line (set in the product's Inventory card).": "Darauf oder darunter gilt als niedrig, für jedes Produkt ohne eigene Grenze (in der Bestandskarte des Produkts).",
 "At the check": "Bei der Prüfung",
 "At the end of the period": "Am Ende des Zeitraums",
