 "Automatic": "Automatisch",
 "Automatic translation isn't set up on Storelib yet. You can still write each translation yourself.": "Die automatische Übersetzung ist in Storelib noch nicht eingerichtet. Du kannst jede Übersetzung selbst schreiben.",
 "Automatic translation keeps these words as written, or always uses your translation. Translations you write yourself are never changed.": "Die automatische Übersetzung lässt diese Wörter wie geschrieben oder nimmt immer deine Übersetzung. Übersetzungen, die du selbst schreibst, werden nie geändert.",
 "Automatic translation leaves product titles as you wrote them. You can still translate a title yourself on the product's Translations card.": "Die automatische Übersetzung lässt Produkttitel so, wie du sie geschrieben hast. Einen Titel kannst du trotzdem selbst übersetzen, auf der Karte Übersetzungen des Produkts.",
