 "Automatic updates turn on when Storelib's tracking is set up. Until then, orders keep the statuses you set and the carrier's tracking link, and buyers get the same emails when you change a status.": "Automatische Updates starten, sobald Storelibs Sendungsverfolgung eingerichtet ist. Bis dahin behalten Bestellungen die Status, die du setzt, und den Tracking-Link des Versanddienstes, und Käufer bekommen dieselben E-Mails, wenn du einen Status änderst.",
