 "Cancel order on the buyer's order page while the order is still Unfulfilled. It is cancelled and refunded in full at once, its stock goes back on sale and you get an email. An order already sent to a print partner or an app asks you first.": "„Bestellung stornieren“ auf der Bestellseite des Käufers, solange die Bestellung noch nicht ausgeführt ist. Sie wird sofort storniert und vollständig erstattet, der Bestand wird wieder freigegeben und du bekommst eine E-Mail. Eine Bestellung, die schon an einen Druckpartner oder eine App gesendet wurde, fragt zuerst dich.",
