 "Changelog": "Neuigkeiten",
 "Changes are saved as you make them and reach your checkout within a few seconds.": "Änderungen werden sofort gespeichert und sind in wenigen Sekunden im Checkout.",
 "Changes one of Storelib's sections in a way it can't use": "Ändert einen Storelib-Abschnitt so, dass er nicht mehr nutzbar ist",
 "Changes one of {oneOfOurs} sections in a way it can't use": "Ändert einen der {oneOfOurs}-Abschnitte auf eine Weise, die er nicht nutzen kann",
 "Changes reach your live checkout within a few seconds. Nothing here touches orders already placed.": "Änderungen sind in wenigen Sekunden im Live-Checkout. Nichts hier betrifft bereits aufgegebene Bestellungen.",
 "Changes saved": "Änderungen gespeichert",
 "Changes since published{value}": "Änderungen seit der Veröffentlichung{value}",
 "Changes to your account and its email address.": "Änderungen an deinem Konto und seiner E-Mail-Adresse.",
 "Changes to your store, checkout, taxes, shipping and integrations show up here.": "Änderungen an Shop, Checkout, Steuern, Versand und Integrationen erscheinen hier.",
 "Changing it signs you out on your other devices.": "Eine Änderung meldet dich auf deinen anderen Geräten ab.",
 "Changing the currency asks what happens to your prices: keep the numbers (100 EUR becomes 100 USD) or convert them at the day's exchange rate. Orders already placed keep their own currency.": "Beim Wechsel der Währung wirst du gefragt, was mit deinen Preisen passiert: die Zahlen behalten (aus 100 EUR wird 100 USD) oder zum Tageskurs umrechnen. Bereits aufgegebene Bestellungen behalten ihre Währung.",
 "Changing the words needs a database update (SQL part 129). The preview still works.": "Zum Ändern der Texte braucht es ein Datenbank-Update (SQL Teil 129). Die Vorschau funktioniert trotzdem.",
 "Channel": "Kanal",
 "Channels": "Kanäle",
