 "Charged through Storelib's Stripe account, at your rate for the buyer's country, on every renewal.": "Abgerechnet über das Stripe-Konto von Storelib, zu deinem Satz für das Land des Käufers, bei jeder Verlängerung.",
 "Charged through Storelib's Stripe account. Stripe Tax works out the rate from where the buyer is, on every renewal.": "Abgerechnet über das Stripe-Konto von Storelib. Stripe Tax ermittelt den Satz danach, wo der Käufer ist, bei jeder Verlängerung.",
