 "Checkout": "Checkout",
 "Checkout always charges your store's own currency and says so next to the total, so a converted price is shown as an estimate.": "An der Kasse wird immer in der Währung deines Shops abgerechnet, was neben der Summe steht, daher ist ein umgerechneter Preis eine Schätzung.",
 "Checkout canceled. Nothing changed.": "Checkout abgebrochen. Nichts wurde geändert.",
 "Checkout charges the visitor's currency, the amounts they saw. A currency Storelib can't charge yet is shown for reference, and checkout says it charges yours.": "Die Kasse rechnet in der Währung des Besuchers ab, mit den Beträgen, die er gesehen hat. Eine Währung, die Storelib noch nicht abrechnen kann, wird nur zur Orientierung gezeigt, und die Kasse sagt, dass in deiner abgerechnet wird.",
 "Checkout charges what your store's prices are in, and says so next to the total, so a converted price is always shown as an estimate.": "Der Checkout berechnet in der Währung deiner Shoppreise und sagt das neben der Summe, ein umgerechneter Preis ist also immer eine Schätzung.",
 "Checkout conversion": "Checkout-Konversion",
 "Checkout for the product they left": "Checkout für das zurückgelassene Produkt",
 "Checkout has no way to get an order to the buyer, so nobody can buy.": "Der Checkout kann keine Bestellung zum Käufer bringen, also kann niemand kaufen.",
 "Checkout is closed until payments are set up again, so buyers cannot pay you in the meantime.": "Der Checkout ist geschlossen, bis Zahlungen neu eingerichtet sind, Käufer können dich so lange nicht bezahlen.",
 "Checkout is the page where a buyer types their details and pays. These settings decide what it asks for.": "Der Checkout ist die Seite, auf der Käufer ihre Daten eingeben und bezahlen. Diese Einstellungen legen fest, was abgefragt wird.",
