 "Drag a tile to move it.": "Ziehe eine Kachel, um sie zu verschieben.",
 "Drag a tile to move it. The first is shown first.": "Ziehe eine Kachel, um sie zu verschieben. Die erste wird zuerst gezeigt.",
 "Drag and drop files or": "Dateien hierher ziehen oder",
