 "Dusk": "Abenddämmerung",
 "Dynamic Favicon": "Dynamisches Favicon",
 "E-books": "E-Books",
 "EN": "EN",
 "EU, {n} countries": "EU, {n} Länder",
 "Each address gets an email from Storelib with a link that works once, for 30 days. Members and anyone invited this week are skipped.": "Jede Adresse bekommt eine E-Mail von Storelib mit einem Link, der einmal und 30 Tage lang gilt. Mitglieder und alle, die diese Woche eingeladen wurden, werden übersprungen.",
 "Each charge lands here with its invoice.": "Jede Abbuchung erscheint hier mit ihrer Rechnung.",
 "Each community's members now, who joined in this period and its visits, one a visitor a day. Open a community for its full analytics.": "Die aktuellen Mitglieder jeder Community, wer in diesem Zeitraum beigetreten ist und ihre Besuche, einer pro Besucher und Tag. Öffne eine Community für alle ihre Statistiken.",
 "Each email goes to each person once, however often they trigger it. Someone who unsubscribes gets nothing more.": "Jede E-Mail geht einmal an jede Person, egal wie oft sie sie auslöst. Wer sich abmeldet, bekommt nichts mehr.",
 "Each invite works once and lasts 30 days. You can see and revoke them under Invites.": "Jede Einladung gilt einmal und 30 Tage lang. Unter Einladungen kannst du sie sehen und widerrufen.",
 "Each item is priced by its own weight, then added up.": "Jeder Artikel wird nach Gewicht berechnet und dann addiert.",
 "Each item pays the price of the step its weight reaches. Two 0.5 {unit} items at a 0 {unit2} step of $3 pay $6.": "Jeder Artikel zahlt den Preis der Stufe, die sein Gewicht erreicht. Zwei Artikel à 0,5 {unit} bei einer 0-{unit2}-Stufe zu 3 $ zahlen 6 $.",
 "Each item pays the step its own weight reaches, then they are added up.": "Jeder Artikel zahlt die Stufe, die sein eigenes Gewicht erreicht, dann wird addiert.",
 "Each language gets its own address, like yourstore.com/fr.": "Jede Sprache hat ihre eigene Adresse, etwa yourstore.com/fr.",
 "Each link needs a label and an https:// address.": "Jeder Link braucht eine Beschriftung und eine https://-Adresse.",
 "Each member reads and accepts these once, before their first message. When you change them, everyone is asked again.": "Jedes Mitglied liest und akzeptiert sie einmal, vor der ersten Nachricht. Wenn du sie änderst, werden alle erneut gefragt.",
 "Each member sees it once, on any device. People already in see it only if they have not yet.": "Jedes Mitglied sieht es einmal, auf jedem Gerät. Wer schon dabei ist, sieht es nur, wenn er es noch nicht gesehen hat.",
 "Each month": "Pro Monat",
 "Each new order for this location is sent here": "Jede neue Bestellung für diesen Standort geht hierhin",
 "Each new order is sent to your own system as a signed request. Set the address in Integrations.": "Jede neue Bestellung geht als signierte Anfrage an dein eigenes System. Leg die Adresse in Integrationen fest.",
 "Each new order with items from here is emailed to this partner with the items and the address. You add their tracking number in Orders when they ship.": "Jede neue Bestellung mit Artikeln von hier wird diesem Partner mit Artikeln und Adresse gemailt. Du trägst die Sendungsnummer in Bestellungen ein, wenn sie versenden.",
 "Each order is printed and shipped for you.": "Jede Bestellung wird für dich gedruckt und versendet.",
 "Each order starts it once. The same order never starts it twice.": "Jede Bestellung startet sie einmal. Dieselbe Bestellung nie zweimal.",
 "Each order with a carrier needs its tracking number. Change the carrier on any order below.": "Jede Bestellung mit Versanddienst braucht ihre Sendungsnummer. Ändere den Versanddienst bei jeder Bestellung unten.",
 "Each page by its exact address and title, with its views and how many people opened it. A page opened again within half an hour counts once.": "Jede Seite mit ihrer genauen Adresse und ihrem Titel, ihren Aufrufen und wie viele Personen sie geöffnet haben. Eine Seite, die innerhalb einer halben Stunde erneut geöffnet wird, zählt einmal.",
 "Each paid order for your CJ location is sent to CJ with the CJ variants you matched, its tracking comes back, and CJ's stock can keep yours in step.": "Jede bezahlte Bestellung für deinen CJ-Standort geht mit den zugeordneten CJ-Varianten an CJ, die Sendungsverfolgung kommt zurück, und CJs Bestand kann deinen abgleichen.",
 "Each paid order for your Gelato location is sent to Gelato with the product and print file you matched, printed near your buyer, and its tracking comes back.": "Jede bezahlte Bestellung für deinen Gelato-Standort geht mit zugeordnetem Produkt und Druckdatei an Gelato, wird nah beim Käufer gedruckt, und die Sendungsverfolgung kommt zurück.",
 "Each paid order for your Printful location is sent to your Printful store by SKU, and its tracking comes back to your buyer.": "Jede bezahlte Bestellung für deinen Printful-Standort geht per SKU an deinen Printful-Shop, und die Sendungsverfolgung kommt zu deinem Käufer zurück.",
 "Each paid order for your Printify location is sent to your Printify shop by SKU, and its tracking comes back to your buyer.": "Jede bezahlte Bestellung für deinen Printify-Standort geht per SKU an deinen Printify-Shop, und die Sendungsverfolgung kommt zu deinem Käufer zurück.",
 "Each paid order is emailed to the location's supplier with the items and the address. Add tracking when they reply.": "Jede bezahlte Bestellung wird dem Lieferanten des Standorts mit Artikeln und Adresse gemailt. Trag die Sendungsnummer ein, wenn er antwortet.",
 "Each paid order is sent to your https address as JSON, signed with your secret (X-Storelib-Signature).": "Jede bezahlte Bestellung geht als JSON an deine https-Adresse, signiert mit deinem Secret (X-Storelib-Signature).",
 "Each paid order you ship goes to ShipStation. Print the label there and the tracking comes back to your buyer.": "Jede bezahlte Versandbestellung geht an ShipStation. Druck dort das Label, die Sendungsverfolgung kommt zu deinem Käufer zurück.",
 "Each policy is a page of your site, linked from its footer. They start as templates: replace anything in square brackets with your own terms before you publish.": "Jede Richtlinie ist eine Seite deiner Website, verlinkt in der Fußzeile. Sie starten als Vorlagen: Ersetze alles in eckigen Klammern durch deine eigenen Bedingungen, bevor du veröffentlichst.",
 "Each product page shows its own": "Jede Produktseite zeigt ihr eigenes",
 "Each product's stock is counted per location. When an order comes in, it is assigned to the default location, and its stock goes down there.": "Der Bestand jedes Produkts wird je Standort gezählt. Eine neue Bestellung wird dem Standardstandort zugewiesen und dort vom Bestand abgezogen.",
 "Each program: how far the members who started it are on average, how many finished it, and how many started it.": "Jedes Programm: wie weit die Mitglieder, die es begonnen haben, im Schnitt sind, wie viele es abgeschlossen und wie viele es begonnen haben.",
 "Each push arrives within seconds, as a draft. Publish when you like it.": "Jeder Push kommt in Sekunden als Entwurf an. Veröffentliche, wenn er dir gefällt.",
 "Each question needs an answer.": "Jede Frage braucht eine Antwort.",
 "Each report is a card on this page.": "Jeder Bericht ist eine Karte auf dieser Seite.",
 "Each rule needs a title.": "Jede Regel braucht einen Titel.",
 "Each sale becomes available about {settleDays} days after it is paid. That wait is set by our payment partner for your country and protects against refunds and disputes.": "Jeder Verkauf wird etwa {settleDays} Tage nach der Zahlung verfügbar. Diese Frist legt unser Zahlungspartner für dein Land fest; sie schützt vor Erstattungen und Anfechtungen.",
 "Each sale becomes available after a short settlement wait set by our payment partner for your country.": "Jeder Verkauf wird nach einer kurzen Abrechnungsfrist verfügbar, die unser Zahlungspartner für dein Land festlegt.",
 "Each variant has its own quantity, in Variants below.": "Jede Variante hat ihre eigene Menge, unten bei Varianten.",
 "Earlier": "Früher",
 "Earlier imports": "Frühere Importe",
 "Earlier visits": "Frühere Besuche",
