 "Imported reviews are marked Imported. They can show on your website, but they never get the Verified purchase label and never count in your Storelib rating.": "Importierte Bewertungen sind als Importiert markiert. Sie können auf deiner Website erscheinen, bekommen aber nie das Label Verifizierter Kauf und zählen nie zu deiner Storelib-Bewertung.",
