 "Its address, once published": "Ihre Adresse, sobald veröffentlicht",
 "Its files and links go with it. This cannot be undone.": "Seine Dateien und Links gehen mit. Das lässt sich nicht rückgängig machen.",
 "Its full page": "Seine ganze Seite",
 "Its items aren't marked shipped. Ship them with it, or void it to get the money back.": "Die Artikel sind nicht als versendet markiert. Versende sie damit oder storniere es, um das Geld zurückzubekommen.",
 "Its link works wherever it's listed. ": "Sein Link funktioniert überall, wo es gelistet ist. ",
 "Its modules, lessons and their files are deleted. This cannot be undone.": "Module, Lektionen und Dateien werden gelöscht. Das lässt sich nicht rückgängig machen.",
 "Its name and cover are the course's own.": "Name und Titelbild stammen vom Kurs.",
 "Its own height": "Eigene Höhe",
 "Its pages, settings and code are deleted. Export first to keep a copy.": "Seiten, Einstellungen und Code werden gelöscht. Exportiere vorher, um eine Kopie zu behalten.",
 "Its photos, price, variants and how many you have.": "Fotos, Preis, Varianten und wie viele du hast.",
 "Its product is no longer in your store. Take it out of the library.": "Sein Produkt ist nicht mehr in deinem Shop. Nimm es aus der Bibliothek.",
 "Its size and weight make shipping by weight and labels right.": "Größe und Gewicht machen gewichtsbasierten Versand und Labels genau.",
 "Its steps and history go with it.": "Ihre Schritte und ihr Verlauf verschwinden mit ihr.",
 "Its stock goes back on sale. The payment isn't refunded by this: use Refund on the order for that.": "Der Bestand geht zurück in den Verkauf. Die Zahlung wird dadurch nicht erstattet: Nutz dafür „Erstatten“ in der Bestellung.",
 "Its video and files go too, and buyers lose the lesson.": "Video und Dateien verschwinden auch, und Käufer verlieren die Lektion.",
 "Its weight is added to every parcel, so rates by weight come out right.": "Sein Gewicht wird zu jedem Paket addiert, damit Gewichtstarife stimmen.",
 "Its words and colours are set in Theme settings.": "Texte und Farben stellst du in den Theme-Einstellungen ein.",
 "Its words, its style and a short line under it.": "Seine Worte, sein Stil und eine kurze Zeile darunter.",
 "Its {length, plural, one {# lesson} other {# lessons}}, their videos and files go too, and buyers lose them.": "{length, plural, one {Seine # Lektion} other {Seine # Lektionen}}, ihre Videos und Dateien verschwinden auch, und Käufer verlieren sie.",
