 "Of members at the start": "Der Mitglieder zu Beginn",
 "Of the emails sent in this period, how many had a link clicked.": "Bei wie vielen der in diesem Zeitraum gesendeten E-Mails ein Link angeklickt wurde.",
 "Of the emails sent in this period, how many were opened.": "Wie viele der in diesem Zeitraum gesendeten E-Mails geöffnet wurden.",
 "Of the emails your automations sent, how many were opened. Some mail apps hide opens, so this is a floor.": "Wie viele der von deinen Automatisierungen gesendeten E-Mails geöffnet wurden. Manche Mail-Apps verbergen Öffnungen, das ist also ein Mindestwert.",
 "Of the people who visited, how many opened a product, added it to the cart or pressed Buy, started a checkout, and how many orders came in. Each step is a share of the one before; the step that loses the most people is marked in red.": "Von den Besuchern: wie viele ein Produkt geöffnet, es in den Warenkorb gelegt oder Kaufen gedrückt, einen Checkout begonnen haben, und wie viele Bestellungen kamen. Jeder Schritt ist ein Anteil des vorherigen; der Schritt mit den meisten Abgängen ist rot markiert.",
 "Of the people who visited, how many opened a product, how many started a checkout, and how many orders came in. Each step is shown as a share of the one before.": "Von den Besuchern: wie viele ein Produkt geöffnet, wie viele einen Checkout begonnen haben und wie viele Bestellungen eingingen. Jeder Schritt wird als Anteil des vorherigen gezeigt.",
