 "Off topic": "Themenfremd",
 "Off, buyers pay your prices and nothing more.": "Aus zahlen Käufer deine Preise und nichts weiter.",
 "Off, each order is made in CJ unpaid, and waits until you pay it there. On, it is confirmed and paid from your CJ balance as soon as your buyer pays.": "Aus wird jede Bestellung unbezahlt in CJ angelegt und wartet, bis du sie dort bezahlst. An wird sie bestätigt und aus deinem CJ-Guthaben bezahlt, sobald dein Käufer zahlt.",
 "Off, each order waits in {name} as a draft until you approve it there, and {name2} charges you only then. On, it is made and charged as soon as it is paid.": "Aus wartet jede Bestellung in {name} als Entwurf, bis du sie dort freigibst, und {name2} berechnet dich erst dann. An wird sie erstellt und berechnet, sobald sie bezahlt ist.",
