 "Once it has passed, say": "Danach anzeigen",
 "Once it is available you can cash it out, and it usually reaches your bank in 1 to 3 business days.": "Sobald es verfügbar ist, kannst du es auszahlen; es kommt meist in 1 bis 3 Werktagen bei deiner Bank an.",
 "Once it starts it cannot be taken back. You can stop the ones not yet sent.": "Einmal gestartet, lässt es sich nicht zurücknehmen. Du kannst die noch nicht gesendeten stoppen.",
 "Once per person": "Einmal pro Person",
 "Once saved, they'll appear on your OnePage.": "Nach dem Speichern erscheinen sie auf deiner OnePage.",
 "Once the items are back, mark them received: you choose whether they go back into stock, and you refund the buyer from the same screen.": "Sind die Artikel zurück, markier sie als erhalten: Du wählst, ob sie zurück in den Bestand gehen, und erstattest dem Käufer im selben Bildschirm.",
 "Once, now or at a time": "Einmal, jetzt oder zu einer Uhrzeit",
