 "One email a day at most, listing what sold down to its low stock line.": "Höchstens eine E-Mail pro Tag mit allem, was bis zur Grenze verkauft wurde.",
 "One email a day per community, so your members keep reading them.": "Eine E-Mail pro Tag und Community, damit deine Mitglieder sie weiter lesen.",
 "One email an hour later with a link back to what they chose, only to buyers who ticked the news box. It stops the moment they buy.": "Eine E-Mail eine Stunde später mit einem Link zu ihrer Auswahl, nur an Käufer mit angehaktem Newsletter-Feld. Stoppt, sobald sie kaufen.",
 "One email an hour later, only to buyers who ticked the news box. With the news box hidden nobody can tick it, so no reminder goes out.": "Eine E-Mail eine Stunde später, nur an Käufer mit angehaktem Newsletter-Feld. Ist das Feld ausgeblendet, kann es niemand anhaken, also geht keine Erinnerung raus.",
 "One email listing every parcel and its tracking link.": "Eine E-Mail mit jedem Paket und seinem Sendungslink.",
 "One email per order listing its parcels and tracking links.": "Eine E-Mail pro Bestellung mit ihren Paketen und Sendungslinks.",
 "One email per order with its tracking link, or saying it's on the way.": "Eine E-Mail pro Bestellung mit ihrem Sendungslink oder dem Hinweis, dass sie unterwegs ist.",
 "One emoji, or up to two letters.": "Ein Emoji oder bis zu zwei Buchstaben.",
