 "Only Storelib sees this.": "Nur Storelib sieht das.",
 "Only YouTube and Vimeo links can be added as a video.": "Nur YouTube- und Vimeo-Links können als Video hinzugefügt werden.",
 "Only a community anyone can join is shown. Change that under Access and prices.": "Nur eine Community, der jeder beitreten kann, wird gezeigt. Das änderst du unter Zugang und Preise.",
 "Only approved translations show, and only once a language is published. Anything not translated yet shows in your default language, never blank.": "Nur freigegebene Übersetzungen erscheinen, und erst, wenn die Sprache veröffentlicht ist. Noch nicht Übersetztes erscheint in deiner Standardsprache, nie leer.",
 "Only buyers in {country} can order. You can add more places later.": "Nur Käufer in {country} können bestellen. Du kannst später weitere Orte hinzufügen.",
 "Only buyers who asked for your news": "Nur Käufer, die deine Neuigkeiten wollten",
 "Only changes the builder. In another language, the sidebar edits that language's text.": "Ändert nur den Editor. In einer anderen Sprache bearbeitet die Seitenleiste den Text dieser Sprache.",
 "Only changes what you see here. Visitors choose their own.": "Ändert nur, was du hier siehst. Besucher wählen selbst.",
 "Only for collections": "Nur für Kollektionen",
 "Only for me": "Nur für mich",
 "Only if {phrase}": "Nur wenn {phrase}",
 "Only its author can add files and videos to this post.": "Nur die Person, die den Beitrag verfasst hat, kann Dateien und Videos hinzufügen.",
 "Only links and images go in a group.": "In eine Gruppe passen nur Links und Bilder.",
 "Only members ever see Learn. This decides which of them can open the lessons.": "Nur Mitglieder sehen Lernen. Das hier legt fest, wer von ihnen die Lektionen öffnen kann.",
 "Only members ever see Learn. This decides which of them open the lessons.": "Nur Mitglieder sehen Lernen. Das entscheidet, wer von ihnen die Lektionen öffnet.",
 "Only members ever see the Library. This decides which of them open it.": "Nur Mitglieder sehen die Bibliothek. Hier legst du fest, wer von ihnen es öffnet.",
 "Only members on the tiers you pick.": "Nur Mitglieder der Stufen, die du wählst.",
 "Only on orders over": "Nur bei Bestellungen über",
 "Only on orders over an amount": "Nur bei Bestellungen über einem Betrag",
 "Only one currency can be for all other countries.": "Nur eine Währung kann für alle anderen Länder gelten.",
 "Only orders delivered to these countries. Pickups can always pay in cash.": "Nur Bestellungen, die in diese Länder geliefert werden. Abholungen können immer bar bezahlt werden.",
 "Only orders placed after you turn the app on are asked. Buyers who turned review emails off, or already reviewed, are never asked.": "Nur Bestellungen nach dem Einschalten der App werden angefragt. Käufer, die Bewertungs-E-Mails abgeschaltet oder schon bewertet haben, werden nie gefragt.",
 "Only people who asked for your news get it.": "Nur Personen, die deine Neuigkeiten wollten, bekommen sie.",
 "Only people who trigger it after you turn it on are sent anything. Someone who unsubscribes is never sent another email, wherever they are in the flow.": "Nur wer sie nach dem Einschalten auslöst, bekommt etwas. Wer sich abmeldet, bekommt nie wieder eine E-Mail, egal wo im Ablauf.",
 "Only people you invite": "Nur Leute, die du einlädst",
 "Only photos and MP4, WebM or MOV videos.": "Nur Fotos und MP4-, WebM- oder MOV-Videos.",
 "Only some states or provinces": "Nur einige Bundesstaaten oder Provinzen",
 "Only the first 2,000 rows are read. Import the rest as another file.": "Nur die ersten 2.000 Zeilen werden gelesen. Importiere den Rest als weitere Datei.",
 "Only the first {n} rows are read. Import the rest as a second file.": "Nur die ersten {n} Zeilen werden gelesen. Importiere den Rest als zweite Datei.",
 "Only the members you pick. Nobody else sees it.": "Nur die Mitglieder, die du auswählst. Sonst sieht es niemand.",
 "Only the products below use these rates.": "Nur die Produkte unten nutzen diese Tarife.",
 "Only the team sees it.": "Nur das Team sieht ihn.",
 "Only the team starts conversations. Members can answer them.": "Nur das Team startet Unterhaltungen. Mitglieder können antworten.",
 "Only these products": "Nur diese Produkte",
 "Only to buyers who have not reviewed yet.": "Nur an Käufer, die noch nicht bewertet haben.",
 "Only to people who asked for your news": "Nur an Personen, die deine Neuigkeiten wollten",
 "Only verified buyers count toward your Storelib rating and get the Verified purchase label. Imported and visitor reviews can show on your website, but never count there.": "Nur verifizierte Käufer zählen zu deiner Storelib-Bewertung und bekommen das Label Verifizierter Kauf. Importierte Bewertungen und Bewertungen von Besuchern können auf deiner Website erscheinen, zählen dort aber nie.",
 "Only web addresses (https://) can be links.": "Nur Webadressen (https://) können Links sein.",
