 "Optional. Visitors from other countries see your prices in their currency and pay in it.": "Optional. Besucher aus anderen Ländern sehen deine Preise in ihrer Währung und zahlen darin.",
 "Optional. Visitors in the countries you list see prices in that currency and pay in it. Everyone else sees {currency}. Anyone can switch with your website's currency selector.": "Optional. Besucher in den Ländern, die du angibst, sehen die Preise in dieser Währung und zahlen darin. Alle anderen sehen {currency}. Jeder kann mit der Währungsauswahl deiner Website wechseln.",
