 "Stripe asks for these four digits to confirm who you are.": "Stripe fragt nach diesen vier Ziffern, um zu bestätigen, wer du bist.",
 "Stripe checks your ID to confirm you are who you say you are. It goes straight to Stripe, and Storelib never sees or keeps the document.": "Stripe prüft deinen Ausweis, um zu bestätigen, dass du du bist. Er geht direkt an Stripe, Storelib sieht oder speichert das Dokument nie.",
 "Stripe has your ID.": "Stripe hat deinen Ausweis.",
 "Stripe is checking it. This usually takes under a minute.": "Stripe prüft ihn. Das dauert meist unter einer Minute.",
 "Stripe is checking your ID. You can close this and go back to Storelib; we will tell you the moment it is done.": "Stripe prüft deinen Ausweis. Du kannst das schließen und zu Storelib zurückkehren; wir sagen dir Bescheid, sobald es fertig ist.",
 "Stripe is saving the photo. If it doesn't answer, take it again.": "Stripe speichert das Foto. Wenn keine Antwort kommt, nimm es neu auf.",
 "Stripe is taking a closer look at this one. Nothing more is needed from you, and we'll email you the moment payments are on.": "Stripe schaut sich das genauer an. Du musst nichts weiter tun, wir mailen dir, sobald Zahlungen aktiv sind.",
