 "The newest exchange rates are from {asOf}, which is too old to use. Markets show your own prices until new rates arrive.": "Die neuesten Wechselkurse sind vom {asOf} und zu alt. Märkte zeigen deine eigenen Preise, bis neue Kurse da sind.",
 "The number sold, on the product page": "Die verkaufte Menge auf der Produktseite",
 "The order confirmation and every update a buyer gets from your store.": "Die Bestellbestätigung und jedes Update, das ein Käufer von deinem Shop bekommt.",
 "The order did not save.": "Die Reihenfolge wurde nicht gespeichert.",
 "The order goes to {name} by each variant's SKU, and its tracking comes back to your buyer by itself.": "Die Bestellung geht per SKU jeder Variante an {name}, und die Sendungsverfolgung kommt automatisch zu deinem Käufer zurück.",
 "The order is gone": "Die Bestellung gibt es nicht mehr",
 "The order is still loading.": "Die Bestellung lädt noch.",
 "The order moves to the new address, and the receipt with the download link is sent there now.": "Die Bestellung geht an die neue Adresse, und der Beleg mit dem Download-Link wird jetzt dorthin gesendet.",
 "The order moves to the new address. Nothing is sent, as nothing in it has been paid for yet.": "Die Bestellung geht an die neue Adresse. Es wird nichts gesendet, da noch nichts bezahlt ist.",
 "The order pays the price of the last step it reaches. The first step starts from 0. A $0 step is free shipping from there.": "Die Bestellung zahlt den Preis der letzten erreichten Stufe. Die erste Stufe beginnt bei 0. Eine 0-$-Stufe bedeutet ab dort kostenlosen Versand.",
 "The order pays the price of the last step its weight reaches, products plus your default package. The first step starts from 0.": "Die Bestellung zahlt den Preis der letzten Stufe, die ihr Gewicht erreicht, Produkte plus Standardpaket. Die erste Stufe beginnt bei 0.",
 "The order pays the step its total reaches. A step at 0 is free shipping from there.": "Die Bestellung zahlt die Stufe, die ihre Summe erreicht. Eine Stufe mit 0 ist ab dort kostenloser Versand.",
 "The order pays the step its weight reaches, your default package included.": "Die Bestellung zahlt die Stufe, die ihr Gewicht erreicht, deine Standardverpackung eingerechnet.",
 "The order was not saved.": "Die Reihenfolge wurde nicht gespeichert.",
 "The other side of the card. A passport has no back.": "Die andere Seite der Karte. Ein Pass hat keine Rückseite.",
 "The owner and admins write the rules.": "Inhaber und Admins schreiben die Regeln.",
