 "The packing slip could not be made. Try again.": "Der Lieferschein konnte nicht erstellt werden. Versuch es noch einmal.",
 "The packing slips could not be made. Try again.": "Die Lieferscheine konnten nicht erstellt werden. Versuche es erneut.",
 "The page behind the sections, the announcement bar and links outside any section.": "Die Seite hinter den Abschnitten, die Ankündigungsleiste und Links außerhalb von Abschnitten.",
 "The page could not be read. Reload to try again.": "Die Seite konnte nicht gelesen werden. Lade neu, um es erneut zu versuchen.",
 "The page kept its last version. Fix the file on GitHub and push again.": "Die Seite hat ihre letzte Version behalten. Behebe die Datei auf GitHub und pushe erneut.",
 "The page loads files from {count} other services: {hosts}.": "Die Seite lädt Dateien von {count} anderen Diensten: {hosts}.",
 "The page was not served from Storelib's cache, so each visit waits for it to be built.": "Die Seite kam nicht aus dem Cache von Storelib, also wartet jeder Besuch, bis sie erstellt ist.",
