 "The pages opened most, with how many people opened each. A page opened again within half an hour counts once.": "Die meistgeöffneten Seiten und wie viele Personen jede geöffnet haben. Eine Seite, die innerhalb einer halben Stunde erneut geöffnet wird, zählt einmal.",
