 "This product has options, so it sells from its own page. Pick another way to open it.": "Dieses Produkt hat Optionen und wird deshalb auf seiner eigenen Seite verkauft. Wähle einen anderen Weg, es zu öffnen.",
 "This product is live. Save your changes before you go, or leave without them.": "Dieses Produkt ist live. Speichere deine Änderungen, bevor du gehst, oder geh ohne sie.",
