 "This product's stock at the CJ location follows CJ's warehouses, read every six hours and when CJ says it changed.": "Der Bestand dieses Produkts am CJ-Standort folgt den CJ-Lagern, alle sechs Stunden gelesen und wenn CJ eine Änderung meldet.",
