 "Visibility and search": "Sichtbarkeit und Suche",
 "Visible": "Sichtbar",
 "Visible to anyone with the link": "Für alle mit dem Link sichtbar",
 "Visit the studio": "Besuch das Studio",
 "Visit {brand}'s website on Storelib": "Besuch die Website von {brand} auf Storelib",
 "Visitor currencies": "Währungen für Besucher",
 "Visitor speed is not set up yet": "Die Geschwindigkeit für Besucher ist noch nicht eingerichtet",
 "Visitors": "Besucher",
 "Visitors are matched by the country they browse from, and can change it with the currency or country selector. Their choice is remembered.": "Besucher werden nach dem Land zugeordnet, aus dem sie surfen, und können es über das Währungs- oder Ländermenü ändern. Ihre Wahl wird gespeichert.",
 "Visitors are matched by the country they browse from, and can change it with the currency selector. Their choice is remembered.": "Besucher werden nach dem Land zugeordnet, aus dem sie surfen, und können es mit der Währungsauswahl ändern. Ihre Wahl wird gespeichert.",
 "Visitors by the system of their device, with its share of all visitors. Read from the browser's signature, and from its platform hint where the signature is vague.": "Besucher nach dem System ihres Geräts, mit Anteil an allen Besuchern. Aus der Kennung des Browsers gelesen, und aus seinem Plattform-Hinweis, wo die Kennung vage ist.",
 "Visitors confirm before it opens": "Besucher bestätigen vor dem Öffnen",
 "Visitors go to {goesTo} for 30 days, then it stops.": "Besucher werden 30 Tage lang zu {goesTo} geleitet, danach endet es.",
 "Visitors in the EU, the UK and Switzerland are counted in full once they accept cookies; before that Google gets a cookieless ping.": "Besucher aus der EU, dem Vereinigten Königreich und der Schweiz werden voll gezählt, sobald sie Cookies akzeptieren; davor bekommt Google einen Ping ohne Cookies.",
 "Visitors may see a different order depending on their location or preferences.": "Besucher sehen je nach Standort oder Vorlieben evtl. eine andere Reihenfolge.",
 "Visitors open the course page, where they can buy it.": "Besucher öffnen die Kursseite und können ihn dort kaufen.",
 "Visitors open your website in your default language and store currency, and switch with your theme's own selectors.": "Besucher öffnen deine Website in deiner Standardsprache und Shopwährung und wechseln mit den Auswahlen deines Themes.",
 "Visitors see a placeholder until you publish again.": "Besucher sehen eine Platzhalterseite, bis du wieder veröffentlichst.",
 "Visitors see a placeholder. {name} was the last one live.": "Besucher sehen eine Platzhalterseite. {name} war zuletzt live.",
 "Visitors see it once {title} is published in Products › Collections.": "Besucher sehen sie, sobald {title} unter Produkte › Kollektionen veröffentlicht ist.",
 "Visitors see the community at this domain. Members sign in on {main}.": "Besucher sehen die Community unter dieser Domain. Mitglieder melden sich auf {main} an.",
 "Visitors see the last version you published.": "Besucher sehen die zuletzt veröffentlichte Version.",
 "Visitors see this once {name} is published and public.": "Besucher sehen das, sobald {name} veröffentlicht und öffentlich ist.",
 "Visitors see your password page until they type the password.": "Besucher sehen deine Passwortseite, bis sie das Passwort eingeben.",
 "Visitors start in": "Besucher starten auf",
 "Visitors switch with the language selector. On a Storelib theme it sits under the footer by itself. On a theme you imported from Shopify it is the theme's own selector, turned on in the editor (Show language, usually in the header or footer).": "Besucher wechseln über das Sprachmenü. In einem Storelib-Theme steht es allein unter der Fußzeile. In einem aus Shopify importierten Theme ist es das eigene Menü des Themes, im Editor eingeschaltet (Show language, meist im Kopfbereich oder in der Fußzeile).",
 "Visitors switch with your theme's language selector. Turn on Show visitors their own language to open a first visit in their browser's language.": "Besucher wechseln mit der Sprachauswahl deines Themes. Schalte Besuchern ihre eigene Sprache zeigen ein, damit ein erster Besuch in der Sprache ihres Browsers öffnet.",
 "Visitors: where visits came from, from their connection. Orders: where buyers are, from the order, with their revenue.": "Besucher: woher die Besuche kamen, nach ihrer Verbindung. Bestellungen: wo die Käufer sind, laut Bestellung, mit ihrem Umsatz.",
 "Visits": "Besuche",
 "Visits older than three days are counted by day, not by hour.": "Besuche, die älter als drei Tage sind, werden pro Tag gezählt, nicht pro Stunde.",
 "Visits to your pages, by day.": "Besuche deiner Seiten, pro Tag.",
 "Visits to your pages. A visit ends after 30 minutes without a page.": "Besuche deiner Seiten. Ein Besuch endet nach 30 Minuten ohne Seitenaufruf.",
 "Visual stability": "Visuelle Stabilität",
 "Voice input cannot hear this language here. Type it instead.": "Die Spracheingabe versteht diese Sprache hier nicht. Tipp es stattdessen.",
 "Voice input needs a connection. Check it and try again.": "Spracheingabe braucht eine Verbindung. Prüf sie und versuch es noch mal.",
 "Voice input stopped before it heard anything. Try again, or type it.": "Die Spracheingabe hat gestoppt, bevor sie etwas gehört hat. Versuch es noch mal oder tipp es.",
 "Void label": "Label stornieren",
 "Void this {providerName} label? {cost} is refunded once the carrier agrees it wasn't used, and the items go back to unfulfilled.": "Dieses {providerName}-Label stornieren? {cost} werden erstattet, sobald der Versanddienst bestätigt, dass es nicht genutzt wurde, und die Artikel gehen zurück auf unerledigt.",
 "Voided": "Storniert",
