 "What you hear about": "Worüber du informiert wirst",
 "What you hear about from this community": "Was du aus dieser Community erfährst",
 "What you pick when you refund an order. It stays on the order's timeline.": "Was du beim Erstatten einer Bestellung wählst. Es bleibt im Verlauf der Bestellung.",
 "What you price in. Visitors anywhere not listed under More currencies see prices in it and pay in it.": "Die Währung deiner Preise. Besucher überall, was nicht unter Weitere Währungen steht, sehen die Preise darin und zahlen darin.",
 "What you price in. Visitors in {country}, and anywhere not listed under More currencies, see prices in it and pay in it.": "Die Währung deiner Preise. Besucher in {country} und überall, was nicht unter Weitere Währungen steht, sehen die Preise darin und zahlen darin.",
 "What you will cover and who it is for": "Was du behandelst und für wen es ist",
 "What you wrote in this email is replaced.": "Was du in dieser E-Mail geschrieben hast, wird ersetzt.",
 "What your buyers and members get from you, and when: digital products, physical products and communities, each apart. Open one to see it as it is sent and change its words. A reply comes to your contact email.": "Was deine Käufer und Mitglieder von dir bekommen, und wann: digitale Produkte, physische Produkte und Communities, jeweils getrennt. Öffne eine E-Mail, um sie so zu sehen, wie sie gesendet wird, und ihre Worte zu ändern. Eine Antwort geht an deine Kontakt-E-Mail.",
 "What your buyers get from you, and when. Open one to see it and change its words. Each goes out with your store's name, and a reply comes to your contact email.": "Was deine Käufer von dir bekommen und wann. Öffne eine, um sie zu sehen und den Text zu ändern. Jede geht mit deinem Shopnamen raus, Antworten kommen an deine Kontakt-E-Mail.",
 "What your completed sales took in over this period, before fees and refunds.": "Was deine abgeschlossenen Verkäufe in diesem Zeitraum eingebracht haben, vor Gebühren und Erstattungen.",
 "What your website is written in now. It keeps its addresses as they are.": "In welcher Sprache deine Website gerade geschrieben ist. Ihre Adressen bleiben, wie sie sind.",
