 "When their paid time runs out": "Wenn die bezahlte Zeit abläuft",
 "When they go": "Wann sie rausgehen",
 "When visitors subscribe, they can download \"": "Wenn Besucher abonnieren, können sie „",
 "When will my order arrive?": "Wann kommt meine Bestellung an?",
 "When you add a product, ship an order or change a setting, it shows up here.": "Wenn du ein Produkt hinzufügst, eine Bestellung versendest oder eine Einstellung änderst, erscheint es hier.",
 "When you approve a request to join": "Wenn du eine Beitrittsanfrage annimmst",
 "When you approve a request to join. In a paid community it says how to finish joining.": "Wenn du eine Beitrittsanfrage annimmst. In einer bezahlten Community steht darin, wie der Beitritt abgeschlossen wird.",
 "When you approve a return, with your instructions.": "Wenn du eine Rücksendung freigibst, mit deinen Hinweisen.",
 "When you cancel a paid event. It says the money is on its way.": "Wenn du ein bezahltes Event absagst. Darin steht, dass das Geld unterwegs ist.",
 "When you cancel an order before it ships.": "Wenn du eine Bestellung vor dem Versand stornierst.",
 "When you change the shipping address on an order before it ships.": "Wenn du die Lieferadresse einer Bestellung vor dem Versand änderst.",
 "When you change the tracking number on a shipment that already went out.": "Wenn du die Sendungsnummer einer bereits verschickten Sendung änderst.",
 "When you decline a return, with your note.": "Wenn du eine Rücksendung ablehnst, mit deiner Notiz.",
 "When you give someone a ticket.": "Wenn du jemandem ein Ticket gibst.",
 "When you invite someone by email": "Wenn du jemanden per E-Mail einlädst",
 "When you invite someone by email.": "Wenn du jemanden per E-Mail einlädst.",
 "When you mark a pickup order ready.": "Wenn du eine Abholbestellung als bereit markierst.",
 "When you mark it collected.": "Wenn du es als abgeholt markierst.",
 "When you mark items shipped, with the tracking.": "Wenn du Artikel als versendet markierst, mit Sendungsverfolgung.",
 "When you post an announcement": "Wenn du eine Ankündigung postest",
 "When you publish changes, new and edited text is translated into your other languages within a few minutes. Translations you edit yourself are never replaced.": "Wenn du Änderungen veröffentlichst, wird neuer und geänderter Text in wenigen Minuten in deine anderen Sprachen übersetzt. Übersetzungen, die du selbst bearbeitest, werden nie ersetzt.",
 "When you published": "Beim Veröffentlichen",
 "When you refund a download, course or membership, here or in Stripe. Its download stops working.": "Wenn du einen Download, einen Kurs oder eine Mitgliedschaft erstattest, hier oder in Stripe. Der Download funktioniert dann nicht mehr.",
 "When you refund all or part of an order, here or in Stripe.": "Wenn du eine Bestellung ganz oder teilweise erstattest, hier oder in Stripe.",
 "When you write one. It goes to members who keep community emails on, one a day at most.": "Wenn du eine schreibst. Sie geht an Mitglieder, die Community-E-Mails aktiviert haben, höchstens eine pro Tag.",
 "Where": "Wo",
 "Where are you based?": "Wo bist du ansässig?",
 "Where buyers collect their orders. For your default location, it's also where return emails tell buyers to send items.": "Wo Käufer ihre Bestellungen abholen. Bei deinem Standardstandort ist das auch die Adresse, an die Rücksende-E-Mails Artikel schicken lassen.",
 "Where do you ship from?": "Von wo versendest du?",
 "Where each order was placed: your online store, Storelib (Explore, product and creator pages, communities), your OnePage or a checkout link.": "Wo jede Bestellung aufgegeben wurde: dein Onlineshop, Storelib (Explore, Produkt- und Creator-Seiten, Communities), deine OnePage oder ein Checkout-Link.",
 "Where each visit came from, judged by its first page: a search engine, a social app, an email, another website, or typed in directly.": "Woher jeder Besuch kam, gemessen an seiner ersten Seite: eine Suchmaschine, eine Social-App, eine E-Mail, eine andere Website oder direkt eingegeben.",
