 "With Show visitors their own language on, a first visit opens in the published language the browser asks for, once. A close match, or only the country to go by, gets a small offer on the page instead. A market can also start its countries in its own language. After that the visitor's choice wins, and search engines still see every language at its own address.": "Mit „Besuchern ihre Sprache zeigen“ öffnet ein erster Besuch einmal in der veröffentlichten Sprache, die der Browser wünscht. Bei einer ähnlichen Sprache oder nur dem Land erscheint stattdessen ein kleines Angebot auf der Seite. Ein Markt kann seine Länder auch in seiner eigenen Sprache starten. Danach zählt die Wahl des Besuchers, und Suchmaschinen sehen jede Sprache weiter unter ihrer eigenen Adresse.",
