 "You sign in with {value}. Set a password to sign in with your email too.": "Du meldest dich mit {value} an. Leg ein Passwort fest, um dich auch mit deiner E-Mail anzumelden.",
 "You still have": "Du hast noch",
 "You won't be able to accept payments until your Stripe account is connected and verified.": "Du kannst keine Zahlungen annehmen, bis dein Stripe-Konto verbunden und verifiziert ist.",
 "You won't be able to open {name} until its owner invites you again. Your own account stays as it is.": "Du kannst {name} erst wieder öffnen, wenn der Inhaber dich erneut einlädt. Dein eigenes Konto bleibt, wie es ist.",
 "You'll be charged": "Dir werden",
 "You'll be charged {amount} today for the remaining time in your current billing cycle.": "Dir werden heute {amount} für die restliche Zeit deines aktuellen Abrechnungszeitraums berechnet.",
 "You'll be charged {planPrice}": "Dir werden {planPrice} berechnet",
 "You'll be redirected to Stripe to complete your subscription of": "Du wirst zu Stripe weitergeleitet, um dein Abo abzuschließen:",
 "You'll be redirected to Stripe's secure portal to manage your payment methods": "Du wirst zum sicheren Stripe-Portal weitergeleitet, um deine Zahlungsmethoden zu verwalten",
 "You'll receive a 1099-K if you earned $20,000+ across 200+ transactions in a tax year. Stripe sends official forms directly to your email by January 31.": "Du bekommst ein 1099-K, wenn du in einem Steuerjahr über 20.000 $ mit über 200 Transaktionen verdient hast. Stripe schickt die offiziellen Formulare bis zum 31. Januar direkt per E-Mail.",
 "You'll see delivery options and times at checkout, and you'll get an email with tracking when it ships.": "Lieferoptionen und -zeiten siehst du im Checkout, und beim Versand bekommst du eine E-Mail mit Sendungsverfolgung.",
 "You're all set": "Alles erledigt",
 "You're offline": "Du bist offline",
