 "You're on the list for {name}.": "Du stehst auf der Liste für {name}.",
 "You're on track to receive a 1099-K. Stripe will email it by January 31.": "Du bekommst voraussichtlich ein 1099-K. Stripe schickt es bis zum 31. Januar per E-Mail.",
 "You're ready to accept payments.": "Du kannst Zahlungen annehmen.",
 "You're ready to accept payments. Your sales are paid into your balance and you cash out to your bank.": "Du kannst Zahlungen annehmen. Verkäufe gehen auf dein Guthaben, und du zahlst auf dein Bankkonto aus.",
