 "Your payment went through. It opens here in a moment: refresh the page if it does not.": "Deine Zahlung ist durch. Es öffnet sich hier gleich: Lade die Seite neu, falls nicht.",
 "Your payment went through. The program opens in a moment: refresh the page if it does not.": "Deine Zahlung ist durch. Das Programm öffnet sich gleich: Lade die Seite neu, falls nicht.",
 "Your payments account is disconnected and you set payments up again, on whichever account you like. It is the way to move to a different name, a business, or a different bank country.": "Dein Zahlungskonto wird getrennt, und du richtest Zahlungen neu ein, mit einem Konto deiner Wahl. So wechselst du zu einem anderen Namen, einem Unternehmen oder einem anderen Bankland.",
 "Your payout account needs attention": "Dein Auszahlungskonto braucht Aufmerksamkeit",
