 "Your plan": "Dein Plan",
 "Your plan will downgrade at the end of your current billing cycle. You'll keep all current features until then.": "Dein Plan wird am Ende des aktuellen Abrechnungszeitraums herabgestuft. Bis dahin behältst du alle aktuellen Funktionen.",
 "Your plan, invoices and payment card": "Dein Plan, Rechnungen und Zahlungskarte",
 "Your prices": "Deine Preise",
 "Your prices ({currency})": "Deine Preise ({currency})",
 "Your prices are in it and buyers pay in it. Payouts still arrive in your bank's currency.": "Deine Preise sind in dieser Währung und Käufer zahlen in ihr. Auszahlungen kommen weiterhin in der Währung deiner Bank an.",
 "Your prices are in {baseCurrency}. Cards are charged in {chargeCurrency}. A market in another currency shows an estimate converted at the European Central Bank's rate, and says so before payment.": "Deine Preise sind in {baseCurrency}. Karten werden in {chargeCurrency} belastet. Ein Markt in anderer Währung zeigt eine Schätzung zum Kurs der Europäischen Zentralbank und weist vor der Zahlung darauf hin.",
 "Your prices, your website, the builder and checkout all use it.": "Deine Preise, deine Website, der Editor und der Checkout nutzen sie.",
 "Your product has no stock yet. Add some so buyers can order it.": "Dein Produkt hat noch keinen Bestand. Füg welchen hinzu, damit Käufer bestellen können.",
 "Your products": "Deine Produkte",
 "Your products, pages, customers and orders stay as they are.": "Deine Produkte, Seiten, Kunden und Bestellungen bleiben, wie sie sind.",
 "Your products, pages, customers and orders stay exactly as they are. The Free fee applies to new sales, and the things only Pro has, like your own domain and hidden branding, stop at the end of your paid period.": "Deine Produkte, Seiten, Kunden und Bestellungen bleiben genau, wie sie sind. Für neue Verkäufe gilt die Free-Gebühr, und was nur Pro hat, etwa deine eigene Domain und ausgeblendetes Branding, endet mit dem bezahlten Zeitraum.",
 "Your profile photo, until you choose a logo.": "Dein Profilfoto, bis du ein Logo wählst.",
 "Your profiles as a row of icons": "Deine Profile als Reihe von Symbolen",
 "Your programs and lessons, inside the community.": "Deine Programme und Lektionen, in der Community.",
 "Your questions": "Deine Fragen",
 "Your rates go by weight, so without one they ship at the lightest price.": "Deine Tarife richten sich nach Gewicht, ohne Gewicht wird zum leichtesten Preis versendet.",
