 "Your role can review reports but not remove content.": "Deine Rolle kann Meldungen prüfen, aber keine Inhalte entfernen.",
 "Your role in this community cannot do that.": "Deine Rolle in dieser Community darf das nicht.",
 "Your sales show up here as soon as someone buys, with what they paid and what you keep.": "Deine Verkäufe erscheinen hier, sobald jemand kauft, mit dem bezahlten Betrag und deinem Anteil.",
